(-0.5, -1) [-0.626177 -0.949724] 6 steps
(0.5, 1) [0.626177 0.949724] 6 steps
(1, 1) [1.066666 0.845905] 5 steps
(2, -0.5) [ 1.797652 -0.438305] 5 steps




